html:
{# =========================================================
   Vehicle Allocation & Handover Form (Jinja Print Format)
   Styling technique (rounded-corner tables via border-collapse:separate +
   border-radius+overflow:hidden, accent callout boxes, table-based
   signature block) matches the ir app's Print Formats (e.g.
   Disciplinary Action Summary's .summary-table/.signatures) — a plain
   flexbox signature layout was also silently dropped by wkhtmltopdf,
   which has poor flexbox support, so the table-based signature block
   below is a correctness fix as well as a style match, not just cosmetic.
   ========================================================= #}

{% set company = frappe.db.get_value("Asset", doc.asset, "company") %}
{% set letter_head_name = frappe.db.get_value("Company", company, "default_letter_head") if company else None %}
{% set lh = frappe.db.get_value("Letter Head", letter_head_name, ["source", "content", "image"], as_dict=True) if letter_head_name else None %}

<style>
  @media print { @page { size: A4 portrait; margin: 10mm; } }
  * { box-sizing: border-box; }
  body { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #222222; }

  .vah-letterhead { text-align: center; margin-bottom: 14px; }
  .vah-letterhead img { max-height: 70px; }

  .vah-title { text-align: center; font-size: 18px; font-weight: 700; margin: 0 0 2px; color: #1565c0; }
  .vah-subtitle { text-align: center; font-size: 11px; color: #555555; margin: 0 0 14px; }

  .vah-section-title {
    margin: 20px 0 8px; padding-bottom: 4px; border-bottom: 1px solid #1565c0;
    font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px;
    color: #1565c0; page-break-after: avoid;
  }

  .vah-callout {
    margin: 0 0 10px; padding: 9px 11px; border: 1px solid #d8d8d8; border-left: 4px solid #1565c0;
    border-radius: 6px; background: #fafafa; color: #555555; line-height: 1.4; page-break-inside: avoid;
  }

  table.vah-table {
    width: 100%; border-collapse: separate; border-spacing: 0; border: 1px solid #dddddd;
    border-radius: 8px; overflow: hidden; margin-bottom: 4px;
  }
  table.vah-table th, table.vah-table td {
    padding: 6px 8px; font-size: 10.5px; text-align: left; vertical-align: top;
    border-right: 1px solid #dddddd; border-bottom: 1px solid #dddddd;
  }
  table.vah-table th { background: #f5f5f5; font-weight: 700; }
  table.vah-table th:last-child, table.vah-table td:last-child { border-right: none; }
  table.vah-table tbody tr:last-child td { border-bottom: none; }
  table.vah-table tbody tr:nth-child(odd) td { background: #fafafa; }
  table.vah-table tr { page-break-inside: avoid; }

  table.vah-checklist th { text-align: center; }
  table.vah-checklist td.vah-check-col { text-align: center; width: 46px; }
  table.vah-checklist td.vah-item-col { width: 34%; }

  .vah-signatures { margin-top: 10px; page-break-inside: auto; }
  .vah-signatures table { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .vah-signatures tr { page-break-inside: avoid; }
  .vah-signatures td { border: none; vertical-align: bottom; padding: 30px 20px 12px 0; }
  .vah-sig-line { height: 22px; border-bottom: 1px solid #222222; }
  .vah-sig-label { margin-top: 4px; font-size: 10px; color: #555555; }

  @page {
    @bottom-right { content: "Page " counter(page) " of " counter(pages); font-size: 9px; color: #999999; }
  }
</style>

{% if lh %}
<div class="vah-letterhead">
  {% if lh.source == "Image" and lh.image %}
    <img src="{{ frappe.utils.get_url(lh.image) }}">
  {% elif lh.content %}
    {{ lh.content }}
  {% endif %}
</div>
{% endif %}

<div class="vah-title">Vehicle Allocation &amp; Handover Form</div>
<div class="vah-subtitle">{{ doc.name }} &middot; Valid From {{ frappe.utils.formatdate(doc.valid_from) }}</div>

<div class="vah-section-title">Vehicle Details</div>
{% set lic = frappe.db.get_value("Vehicle Licence", {"fleet_number": doc.asset, "docstatus": 1}, ["registration_number", "chassis", "engine_number", "vin_number"], order_by="issue_date desc", as_dict=True) %}
<table class="vah-table">
  <tr>
    <th style="width:18%;">Asset</th>
    <td style="width:32%;">{{ doc.asset }}{% if doc.asset_name %} - {{ doc.asset_name }}{% endif %}</td>
    <th style="width:18%;">Model</th>
    <td>{{ doc.item_name or "" }}</td>
  </tr>
  <tr>
    <th>Registration Number</th>
    <td>{{ lic.registration_number if lic else "—" }}</td>
    <th>Location</th>
    <td>{{ doc.location or "" }}</td>
  </tr>
  <tr>
    <th>Chassis / VIN</th>
    <td>{{ (lic.chassis or lic.vin_number) if lic else "—" }}</td>
    <th>Engine Number</th>
    <td>{{ lic.engine_number if lic else "—" }}</td>
  </tr>
</table>

<div class="vah-section-title">Driver(s)</div>
{% if doc.drivers %}
<table class="vah-table">
  <thead>
    <tr>
      <th style="width:28%;">Name</th>
      <th style="width:22%;">Designation</th>
      <th style="width:25%;">Signature</th>
      <th style="width:25%;">Date</th>
    </tr>
  </thead>
  <tbody>
    {% for d in doc.drivers %}
    {% set designation = frappe.db.get_value("Employee", d.driver, "designation") %}
    <tr>
      <td>{{ d.driver_name or d.driver }}</td>
      <td>{{ designation or "—" }}</td>
      <td>&nbsp;</td>
      <td>&nbsp;</td>
    </tr>
    {% endfor %}
  </tbody>
</table>
{% else %}
<div class="vah-callout">No Driver assigned — allocated as a shared resource to this Location.</div>
{% endif %}

<div class="vah-section-title">Vehicle Receipt Checklist</div>
<div class="vah-callout">To be completed and signed at the point of physical handover — the signed copy
is the Vehicle Handover Paperwork attached to this allocation.</div>
<table class="vah-table vah-checklist">
  <thead>
    <tr>
      <th class="vah-item-col">Item</th>
      <th class="vah-check-col">OK</th>
      <th class="vah-check-col">Not OK</th>
      <th class="vah-check-col">N/A</th>
      <th>Comments</th>
    </tr>
  </thead>
  <tbody>
    {% for item in [
      "Exterior / Bodywork", "Tyres &amp; Spare Wheel", "Lights &amp; Indicators",
      "Mirrors", "Windscreen &amp; Wipers", "Interior / Upholstery", "Fuel Level",
      "Tools &amp; Jack", "Fire Extinguisher", "First Aid Kit", "Warning Triangle",
      "Registration / Licence Disc", "Documents (Cubby Hole)"
    ] %}
    <tr>
      <td class="vah-item-col">{{ item }}</td>
      <td class="vah-check-col">&#9633;</td>
      <td class="vah-check-col">&#9633;</td>
      <td class="vah-check-col">&#9633;</td>
      <td></td>
    </tr>
    {% endfor %}
  </tbody>
</table>

<div class="vah-section-title">Sign-Off</div>
<div class="vah-signatures">
  <table>
    <tr>
      {% for d in doc.drivers %}
      <td>
        <div class="vah-sig-line"></div>
        <div class="vah-sig-label">{{ d.driver_name or d.driver }} (Driver)<br>Signature &amp; Date</div>
      </td>
      {% endfor %}
      {% if not doc.drivers %}
      <td>
        <div class="vah-sig-line"></div>
        <div class="vah-sig-label">Received By<br>Signature &amp; Date</div>
      </td>
      {% endif %}
      <td>
        <div class="vah-sig-line"></div>
        <div class="vah-sig-label">Issued By (Manager)<br>Signature &amp; Date</div>
      </td>
    </tr>
  </table>
</div>

{% if doc.comments %}
<div class="vah-section-title">Comments</div>
<p>{{ doc.comments }}</p>
{% endif %}
